// Similar: a method that tracks errors and changes status
class ErrorTracker {
  constructor() {
    this.errorCount = 0;
    this.maxErrors = 3;
    this.status = 'OK';
  }

  recordError() {
    this.errorCount++;
    if (this.errorCount >= this.maxErrors) {
      this.status = 'FAILED';
    }
  }
}

